<?php require_once __DIR__ . '/../includes/functions.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ $email=trim($_POST['email']); $password=$_POST['password']; $stmt=db()->prepare('SELECT * FROM admins WHERE email=? LIMIT 1'); $stmt->execute([$email]); $admin=$stmt->fetch(); if($admin && password_verify($password, $admin['password'])){ $_SESSION['admin_id']=$admin['id']; $_SESSION['admin_name']=$admin['name']; redirect('/car-rent-sale-system/admin/dashboard.php'); } set_flash('danger','Invalid login credentials.'); redirect('/car-rent-sale-system/auth/login.php'); } $pageTitle='Admin Login'; require_once __DIR__ . '/../includes/header.php'; ?><div class="container py-5"><div class="row justify-content-center"><div class="col-md-5"><div class="form-box"><h2 class="section-title">Admin Login</h2><form method="post"><div class="mb-3"><label class="form-label">Email</label><input type="email" class="form-control" name="email" required></div><div class="mb-3"><label class="form-label">Password</label><input type="password" class="form-control" name="password" required></div><button class="btn btn-primary w-100">Login</button></form><small class="d-block mt-3">Demo login is included in database.sql</small></div></div></div></div><?php require_once __DIR__ . '/../includes/footer.php'; ?>
